body.script:
(function() {
  var root=document.getElementById('root');
  root.innerHTML="


    <!-- =====================================================
         BACKGROUND
         ===================================================== -->

    <div id="bg"></div>


    <!-- =====================================================
         NAVBAR
         ===================================================== -->

    <div class="navbar">


